import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-11-05","description":"","frontmatter":{"title":"AI 动态 · 2026-11-05","date":"2026-11-05T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-11/ai-news-2026-11-05.md","filePath":"news/2026-11/ai-news-2026-11-05.md","lastUpdated":null}'),s={name:"news/2026-11/ai-news-2026-11-05.md"};function i(o,e,l,p,c,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-11-05" tabindex="-1">AI 动态 · 2026-11-05 <a class="header-anchor" href="#ai-动态-·-2026-11-05" aria-label="Permalink to &quot;AI 动态 · 2026-11-05&quot;">​</a></h1><blockquote><p>截至 2026-11-05。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="dropbox-3-5-亿美元收购-tigris-data-加码-ai-基础设施" tabindex="-1">Dropbox 3.5 亿美元收购 Tigris Data，加码 AI 基础设施 <a class="header-anchor" href="#dropbox-3-5-亿美元收购-tigris-data-加码-ai-基础设施" aria-label="Permalink to &quot;Dropbox 3.5 亿美元收购 Tigris Data，加码 AI 基础设施&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/590c96bda84c.jpg" alt="配图"></p><p>Dropbox 以 3.5 亿美元收购 Tigris Data，交易预计支撑 DBX Agent Cloud 的开发，这是一个面向构建 AI 模型与智能体的开发者的新存储平台。存储层正成为 Agent 基础设施的争夺点。对读者：做 Agent 产品的团队可关注该平台的存储与数据接口设计，评估是否适合作为多租户数据底座。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/05/dropbox-acquires-tigris-data-for-350m-to-bolster-its-ai-iinfrastructure/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="agility-成为首家纯人形机器人上市公司-登陆纳斯达克" tabindex="-1">Agility 成为首家纯人形机器人上市公司，登陆纳斯达克 <a class="header-anchor" href="#agility-成为首家纯人形机器人上市公司-登陆纳斯达克" aria-label="Permalink to &quot;Agility 成为首家纯人形机器人上市公司，登陆纳斯达克&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/98ba2eac9f48.png" alt="配图"></p><p>Agility 在纳斯达克上市，成为首家公开交易的纯人形机器人公司，引发市场对人形机器人赛道估值与商业化进度的审视。对读者：关注其后续财报中的部署量与单位经济性，这比发布会演示更能检验人形机器人是否真正进入规模化交付。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/11/05/agility-is-the-first-pure-humanoid-robot-company-on-the-stock-market-are-you-buying/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="openai-发布-gpt‐6-cyber-面向授权范围的网络安全智能体" tabindex="-1">OpenAI 发布 GPT‑6 Cyber：面向授权范围的网络安全智能体 <a class="header-anchor" href="#openai-发布-gpt‐6-cyber-面向授权范围的网络安全智能体" aria-label="Permalink to &quot;OpenAI 发布 GPT‑6 Cyber：面向授权范围的网络安全智能体&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b789b4c4618b.webp" alt="配图"></p><p>OpenAI 推出 GPT‑6 Cyber，专用于发现可利用漏洞并生成修复方案，训练目标是在授权范围内行动，强调对齐与安全边界。这意味着安全智能体从演示走向可交付的攻防工作流。对读者：若团队有漏洞管理流程，可评估把该模型接入内部授权测试与修复建议环节，但务必先划清授权范围与审计链路。</p><p class="news-entry-source"><a href="https://openai.com/index/introducing-gpt-6-cyber" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-上线个人财务功能-连接账户后直接问钱的事" tabindex="-1">Claude 上线个人财务功能：连接账户后直接问钱的事 <a class="header-anchor" href="#claude-上线个人财务功能-连接账户后直接问钱的事" aria-label="Permalink to &quot;Claude 上线个人财务功能：连接账户后直接问钱的事&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/c6ad9ca5f4f7.webp" alt="配图"></p><p>Anthropic 在 Claude 中推出 Personal Finance，用户可连接自己的账户，直接向 Claude 询问收支、资产等问题并获得直白回答。这是通用助手向高敏感个人数据场景的延伸。对读者：关注其账户连接与数据留存策略，个人用户尝鲜前先确认授权范围，企业则需评估同类金融数据接入的合规边界。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/introducing-personal-finance-in-claude" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-enterprise-增强安全管控-安全中心、推理钩子与集中管理" tabindex="-1">Claude Enterprise 增强安全管控：安全中心、推理钩子与集中管理 <a class="header-anchor" href="#claude-enterprise-增强安全管控-安全中心、推理钩子与集中管理" aria-label="Permalink to &quot;Claude Enterprise 增强安全管控：安全中心、推理钩子与集中管理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/b5443a1fd510.webp" alt="配图"></p><p>Claude Enterprise 新增安全与管理能力，包括安全中心、推理钩子（inference hooks）、集中化管理以及更多访问控制。面向企业安全团队提升可见性与控制力。对读者：正在做企业级 AI 采购的团队可把推理钩子与审计能力列入评估清单，用于满足内部合规与数据治理要求。</p><p class="news-entry-source"><a href="https://claude.com/resources/articles/claude-enterprise-security-updates" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="ricursive-发布-ripple‐65b-preview-apache-2-0-开源权重-terminal‐bench-2-1-得-80-5" tabindex="-1">Ricursive 发布 Ripple‑65B Preview：Apache 2.0 开源权重，Terminal‑Bench 2.1 得 80.5 <a class="header-anchor" href="#ricursive-发布-ripple‐65b-preview-apache-2-0-开源权重-terminal‐bench-2-1-得-80-5" aria-label="Permalink to &quot;Ricursive 发布 Ripple‑65B Preview：Apache 2.0 开源权重，Terminal‑Bench 2.1 得 80.5&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-05">2026-11-05</time></p><p>Ricursive Intelligence 发布 65B 稠密开源权重模型 Ripple‑65B Preview，采用 Apache 2.0 协议，在 Terminal‑Bench 2.1 上得分 80.5，领先美国同类开源模型（含参数量达其 15 倍的模型）。对读者：若在做编码/终端智能体，可将其纳入本地或私有化部署的候选，重点验证长任务稳定性与显存成本。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/04/ricursive-ripple-65b-preview-open-weight-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="openai-推出-gpt‐image‐2-6-flare-与-sunburst-支持-gif、svg-导出与-6-秒生成" tabindex="-1">OpenAI 推出 GPT‑Image‑2.6 Flare 与 Sunburst：支持 GIF、SVG 导出与 6 秒生成 <a class="header-anchor" href="#openai-推出-gpt‐image‐2-6-flare-与-sunburst-支持-gif、svg-导出与-6-秒生成" aria-label="Permalink to &quot;OpenAI 推出 GPT‑Image‑2.6 Flare 与 Sunburst：支持 GIF、SVG 导出与 6 秒生成&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-05">2026-11-05</time></p><p>OpenAI 发布 Images 2.6 及 GPT‑Image‑2.6 Flare、Sunburst API 模型。Flare 最快 6 秒出图，两者新增 GIF 输出、SVG 导出、标记编辑与复杂度参数。对读者：前端与设计工具链可评估 SVG 导出与复杂度参数，用于批量生成图标/插画并控制成本与延迟。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/04/openai-gpt-image-2-6-flare-sunburst/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="together-ai-发布-together-compiler-智能体驱动推理优化-最高提速-2-6-倍" tabindex="-1">Together AI 发布 Together Compiler：智能体驱动推理优化，最高提速 2.6 倍 <a class="header-anchor" href="#together-ai-发布-together-compiler-智能体驱动推理优化-最高提速-2-6-倍" aria-label="Permalink to &quot;Together AI 发布 Together Compiler：智能体驱动推理优化，最高提速 2.6 倍&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-11-05">2026-11-05</time></p><p>Together AI 推出 Together Compiler，用智能体驱动的循环在流量变化时持续重优化推理前向过程，每个模型 24 小时内即可超过最佳 InferenceX 配置，最高达 2.6 倍 TPS。对读者：自建推理服务的团队可关注这类自动调优思路，把性能优化从人工调参转为持续运行的编译回路。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/11/05/together-ai-together-compiler-continual-compilation-ai-inference/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="mcp-c-sdk-2-0-默认启用-http-无状态模式-新增多轮请求能力" tabindex="-1">MCP C SDK 2.0 默认启用 HTTP 无状态模式，新增多轮请求能力 <a class="header-anchor" href="#mcp-c-sdk-2-0-默认启用-http-无状态模式-新增多轮请求能力" aria-label="Permalink to &quot;MCP C SDK 2.0 默认启用 HTTP 无状态模式，新增多轮请求能力&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-05">2026-11-05</time></p><p>微软发布官方 MCP C# SDK 2.0，适配 MCP 规范 2026‑07‑28 修订版，HTTP 层重构为无状态设计，支持多轮往返请求（MRTR）与动态能力协商，移除 initialize 握手与 Mcp‑Session‑Id 头。对读者：.NET 技术栈接入 MCP 的团队应尽快评估升级，无状态模式对水平扩展与网关部署更友好。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/80iUxvCNB59aOgyXB7LN?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="谷歌开源-ml-drift-跨平台-gpu-推理引擎加速端侧-ai" tabindex="-1">谷歌开源 ML Drift：跨平台 GPU 推理引擎加速端侧 AI <a class="header-anchor" href="#谷歌开源-ml-drift-跨平台-gpu-推理引擎加速端侧-ai" aria-label="Permalink to &quot;谷歌开源 ML Drift：跨平台 GPU 推理引擎加速端侧 AI&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-11-05">2026-11-05</time></p><p>谷歌推出开源跨平台 GPU 计算引擎 ML Drift，面向端侧 AI 与机器学习推理，统一抽象 OpenGL ES、OpenCL、Metal 与 WebGPU，支撑 LiteRT 运行时，支持五维张量与自定义算子。对读者：做端侧或 WebGPU 推理的团队可评估其算子覆盖与后端适配，作为跨平台部署的候选方案。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/hHzARIJTeqoqYpjNKEuq?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="node-27-首个-alpha-发布-新发布节奏下的破坏性变更" tabindex="-1">Node 27 首个 alpha 发布：新发布节奏下的破坏性变更 <a class="header-anchor" href="#node-27-首个-alpha-发布-新发布节奏下的破坏性变更" aria-label="Permalink to &quot;Node 27 首个 alpha 发布：新发布节奏下的破坏性变更&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Node Weekly</span><time datetime="2026-11-05">2026-11-05</time></p><p>Node.js 27 首个 alpha 按新发布模型推出，每个大版本在稳定前有六个月 alpha 期，正式版预计明年四月。V8 15.6 默认带来 Math.sumPrecise()、Iterator.zip() 等迭代器辅助方法，import defer 与不可变 ArrayBuffer 需开启标志，默认堆上限改为物理内存一半。对读者：库作者应尽早在此 alpha 上跑测试，普通项目暂勿用于生产。</p><p class="news-entry-source"><a href="https://nodeweekly.com/issues/646" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="safari-technology-preview-256-发布" tabindex="-1">Safari Technology Preview 256 发布 <a class="header-anchor" href="#safari-technology-preview-256-发布" aria-label="Permalink to &quot;Safari Technology Preview 256 发布&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">WebKit Blog</span><time datetime="2026-11-05">2026-11-05</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-11/85c6522e4185.jpg" alt="配图"></p><p>WebKit 发布 Safari Technology Preview 256，面向 macOS Golden Gate 与 macOS Tahoe 提供下载。该版本延续对 Web 平台新特性的预览与验证。对读者：关注跨浏览器兼容的前端团队可安装该预览版，提前验证新 API 与 CSS 特性在 Safari 下的表现，减少上线后的兼容返工。</p><p class="news-entry-source"><a href="https://webkit.org/blog/18602/release-notes-for-safari-technology-preview-256/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const u=a(s,[["render",i]]);export{m as __pageData,u as default};
